L21_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_EPISODE_SUB_DOLL"
L22_1 = "Eternium, extrahiert aus den Testobjekten des Forschungslabors der Nordvereinigung. Es hat eine andere Farbe als gew\195\182hnliches Eternium."
L20_1[1] = L21_1
L20_1[2] = L22_1
