L39_1 = "SI_UNIT_SKILL_DESC_ESPR_CA_SHADOW_SKILL_LV5"
L40_1 = "Beim Wirken einer Spezialf\195\164higkeit: Ultimate-Cooldown -5\194\160s"
L38_1[1] = L39_1
