L37_1 = "SI_ITEM_USERTITLE_DESC_1500111"
L38_1 = "Ein ehrenvoller Titel, der dem absoluten Herrscher verliehen wird, der nach zahlreichen Erkundungen und Verfolgungsjagden das Ende erkl\195\164rt hat."
