L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_2_1"
L25_1 = "In vielen Regionen tauchen Volksm\195\164rchen \195\188ber menschenfressende Geister auf. Man kann jedoch sagen, dass es selten vorkommt, dass sie eine Familie gr\195\188nden. Unabh\195\164ngig davon, ob es wahr ist oder nicht, muss es einen Grund f\195\188r die Verbreitung dieser Volksm\195\164rchen geben."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_UNIT_SKILL_DESC_ESPR_S_DOCTOR_PASSIVE_LV1"
L26_1 = "Jeder Standardangriff heilt 2 % der LP aller verb\195\188ndeter Einheiten in Reichweite des Standardangriffs."
