L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT5_INTERLUDE3"
L38_1 = "Die Welt dr\195\164ngt uns immer dazu, einen Sinn in unserem Leben zu finden. Aber niemand sagt uns, dass unsere Berufung im Leben tief in uns selbst zu finden ist."
L36_1[1] = L37_1
