L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_4_2"
L17_1 = "Jede Hoffnung, die Sie haben k\195\182nnten, w\195\164re vergeblich. Ihr blo\195\159er Anblick w\195\188rde Sie n\195\164mlich \195\188berw\195\164ltigen. Wenn sie geweckt wird, wird sie unberechenbar sein. Wer k\195\182nnte ihr jemals Paroli bieten? Niemand auf dieser gro\195\159en weiten Welt."
L15_1[1] = L16_1
L15_1[2] = L17_1
