L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_1"
L40_1 = "Das \195\156berlassen der Beute ist der h\195\182chste Ausdruck der Zuneigung zu einem Raubtier."
L38_1[1] = L39_1
L38_1[2] = L40_1
