L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_5_ACT4_INTERLUDE_1"
L42_1 = "CRS ist eine realit\195\164tsver\195\164ndernde Kraft, oder mit anderen Worten, menschliches Potenzial.\nSie besitzen unglaubliche Kr\195\164fte. Doch anstatt diese Kr\195\164fte bewusst einzusetzen, verbringen sie ihr ganzes Leben damit, sie zu verschwenden."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_2_2"
L43_1 = "Counter m\195\188ssen emotional stabil sein. Psychische Unruhen, die durch intensive Emotionen verursacht werden, sind der Hauptgrund daf\195\188r, dass CRS so schwierig zu kontrollieren ist. Mit anderen Worten: Indem sie ihre Emotionen kontrollieren k\195\182nnen, k\195\182nnen sie ihre F\195\164higkeiten verbessern."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP9_5_2_2"
L44_1 = "Bruch"
