L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_3"
L45_1 = "Bitte seien Sie nicht beunruhigt, wenn Sie die Anwesenheit eines anderen sp\195\188ren. Es ist nichts als das Rascheln der Schreie toter Bl\195\164tter."
L43_1[1] = L44_1
L43_1[2] = L45_1
