L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_4_INTERLUDE_4"
L15_1 = "Durch die Stille sprach sie: \226\128\158Musik ist die Autorit\195\164t, die uns gegeben wird. So werden wir in der Harmonie die verborgene Wahrheit finden, die uns mit allem zu verschmelzen verhilft.\n\226\128\147 Eine Zeile aus einer Schrift, die in den variablen Tiefenkoordinaten gefunden wurde"
L13_1[1] = L14_1
L13_1[2] = L15_1
