L34_1 = {}
L35_1 = "SI_OPERATION_DESC_TEXT_CHALLENGE_RELIC_3"
L36_1 = "Ein von den Anh\195\164ngern der Gesellschaft l\195\164ngst verlassenes Gebiet. Die gesammelten Kristalle der unwissenden \195\156berbleibsel k\195\182nnen bestimmt andersweitig besser zu gebrauchen sein."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_2_CHALLENGE_RELIC_ACC"
L37_1 = "Ein von den Anh\195\164ngern der Gesellschaft l\195\164ngst verlassenes Gebiet."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_1"
L38_1 = "An der Front wurden t\195\164glich neue J\195\188nglinge der Reihe nach eingesetzt.\n\n<color=#ffd34c>\226\128\147 Die Angriffe der Gegner sind sehr stark. Doch mit einer Barriere kann man den Schaden stark mindern.</color>"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_4"
L39_1 = "Die Manieren der Gesellschaft schreiben vor, dass man geladene G\195\164ste mit einem Festmahl verk\195\182stigt und sie verabschiedet.\n\n<color=#ffd34c>\226\128\147 Die Angriffe der Gegner sind stark, doch es fehlt ihnen an Treffsicherheit.\n\226\128\147 Die Gegner wurden gegen Schaden am Boden verst\195\164rkt und der Totem unterst\195\188tzt die Gegner per Regenerationskraft und Nebenf\195\164higkeit.\n\226\128\147 Schergen, die von Edels F\195\164higkeiten getroffen werden, sterben sofort.</color>"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_CHALLENGE_RELIC_2_1"
L40_1 = "Erinnerung an die erste Schlacht"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_CHALLENGE_RELIC_2_2"
L41_1 = "Ergebnis der ersten Schlacht"
