L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_4"
L42_1 = "Die Befehlshaber ergriffen bis zum bitteren Ende keine Flucht.\n\n<color=#ffd34c>\226\128\147 Die Angriffe der Gegner sind sehr stark. Doch mit einer Barriere kann man den Schaden stark mindern.</color>"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_1_1"
L43_1 = "Der Grundalgorithmus einer autonomen Kampfmaschine ist es, eindringenden Gegnern im eigenen Lager mit Erstangriffen zu begegnen.\n\n<color=#ffd34c>\226\128\147 Die Angriffe von Red Moth erzeugen Buffs, die sich pro getroffenem Ziel stapeln.\n\195\156bersteigen die Buffs ein gewisses Ma\195\159, wird eine m\195\164chtige Ultimate-F\195\164higkeit eingesetzt.</color>"
L41_1[1] = L42_1
