L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_2"
L16_1 = "Das Anwesen war tief und weitl\195\164ufig. Das dunkle Gebiet war gef\195\188llt mit lautstarken Todesk\195\164mpfen hin und her.\n\n<color=#ffd34c>\226\128\147 Die Angriffe der Gegner sind stark, doch es fehlt ihnen an Treffsicherheit.\n\226\128\147 Die Gegner wurden gegen Schaden am Boden verst\195\164rkt und der Totem unterst\195\188tzt die Gegner per Regenerationskraft.</color>"
