L28_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_2_DESC"
L29_1 = "Willst du die F\195\164higkeit eines Bedieners verbessern, kannst du <COLOR=#FFBC00>Bediener mit der gleichen F\195\164higkeit</COLOR> als Material verwenden. Je h\195\182her die Klasse des Materialbedieners, desto h\195\182her sind deine Chancen auf Erfolg. Wenn die Fusion fehlschl\195\164gt, verringert sich die urspr\195\188ngliche Stufe der F\195\164higkeit nicht, die Materialbediener verschwinden aber trotzdem."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_3_DESC"
L30_1 = "Du kannst <COLOR=#FFBC00>Bediener mit einer anderen Nebenf\195\164higkeit</COLOR> als Material verwenden, um diese auf einen Zielbediener zu \195\188bertragen. Der Materialbediener <COLOR=#FFBC00>muss mindestens die gleiche Klasse wie der Zielbediener haben</COLOR>. <COLOR=#FFBC00>Bet\195\164tige die Schaltfl\195\164che \226\128\158Nebenf\195\164higkeit \195\164ndern\226\128\156,</COLOR> um die \195\132nderung durchzuf\195\188hren. Nach der \195\132nderung <COLOR=#FFBC00>wird deine Nebenf\195\164higkeiten-Stufe auf 1 zur\195\188ckgesetzt</COLOR>."
L28_1[1] = L29_1
