L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_XMAS_1_3"
L9_1 = "Sie konnte sich nicht mehr zur\195\188ckhalten und explodierte f\195\182rmlich. Doch das lie\195\159 sie nur noch verd\195\164chtiger wirken."
L7_1[1] = L8_1
L7_1[2] = L9_1
