L9_1 = "AB_UI_UNIT_VOICE_OPR_ANASTASIA@AB_UI_UNIT_VOICE_OPR_ANASTASIA_FIGHT_LOSE_A"
L10_1 = "Sogar beim Explodieren ist sie wundersch\195\182n\194\160\226\128\166"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_SKIN_DESC_NKM_UNIT_C_HB_GAEUN_NEWYEAR2021"
L11_1 = "Sie kommt im warmen Sonnenlicht am Morgen, der Schnee knirscht unter ihren F\195\188\195\159en\nund sie bringt wunderbare Neuigkeiten.\nIhre Wangen sind von der K\195\164lte und wahrscheinlich auch von der Aufregung ger\195\182tet.\nDas leichte L\195\164cheln auf ihren Lippen k\195\188ndigt einen Neuanfang an.\n\n<color=#ffd34c>HRT Berrys Neujahrs-Sondershow beginnt. Berry-Berry-Einsatz.</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EVENT_ADMIN_2_1"
L12_1 = "Sie k\195\188mmerte sich mehr um die Anzahl der Kanonenkugeln, die sie noch \195\188brig hatte, als um die Zeit, die zwischen ihnen verstrich."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_UNIT_SKILL_DESC_C_FREEDOM_KASUMI_PASSIVE_LV1"
L13_1 = "Vom Spielen kriegt sie nie genug. Stellt 10\194\160% der LP mit Spezialf\195\164higkeiten und Ultimates wieder her."
L11_1[1] = L12_1
L11_1[2] = L13_1
