L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_3"
L10_1 = "Aus dem \226\128\158Task\194\160Planet\226\128\156-Artikel vom 7. M\195\164rz:\nAls die Unterst\195\188tzung eingestellt wurde, verfiel die Ausr\195\188stung und die Angestellten verlie\195\159en das Unternehmen. Erhebliche Leistungseinbu\195\159en f\195\188hrten zu weiteren Budgetk\195\188rzungen.\nDie Verantwortlichen von Daymine sind immer noch besessen von der Frage, wie sie die Kosten senken k\195\182nnen."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_2"
L11_1 = "Aus dem \226\128\158Task\194\160Planet\226\128\156-Artikel vom 7. M\195\164rz:\nTASKFORCE-Unternehmen ben\195\182tigen hervorragende Unterst\195\188tzung und Ausr\195\188stung. Aber die Verantwortlichen von Daymine geizten mit ihren Investitionen und k\195\188rzten immer wieder die Budgets unter dem Vorwand der \226\128\158F\195\182rderung h\195\182herer Effizienz\226\128\156."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_4"
L12_1 = "Aus dem \226\128\158Task\194\160Planet\226\128\156-Artikel vom 7. M\195\164rz:\nLetztendlich gelang es Daymine nicht, bei den Raumkoordinaten, die es nach langer Zeit erlangt hatte, Eternium zu erhalten.\nDaymines Scheitern bietet viele Lehren f\195\188r diejenigen, die in der nun bl\195\188henden TASKFORCE-Branche t\195\164tig sind."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_1"
L13_1 = "Aus dem \226\128\158Task\194\160Planet\226\128\156-Artikel vom 7. M\195\164rz:\n\226\128\166 Nach dem Gro\195\159en L\195\164uterungskrieg geh\195\182rte Daymine zu den Vorreitern in der TASKFORCE-Industrie, doch nun vermeiden sie es, in die Counterside einzutauchen, und nehmen nur noch Unterwerfungsmissionen in verderbten Gebieten an."
L11_1[1] = L12_1
L11_1[2] = L13_1
