L2_1 = "SI_BOSS_DESC_08"
L3_1 = "Eine Offizierin des Replacer-Syndikats. Sie ist ein regenerierter Replacer, der als Arbiter des Terraside-Systems geschaffen wurde.\nLaut Geheimdienst der Administration handelt es sich bei ihr um ein entwickeltes Wesen, das den alten Replacer-Bishop mit nachgemachten Klippot-Faktoren kombiniert.\nSie scheint von den Erinnerungen ihrer Quelle beeintr\195\164chtigt, aber das h\195\164lt sie nicht von der Erf\195\188llung ihrer Pflichten f\195\188r ihre Organisation, das feindselige Replacer-Syndikat, ab.\n\n<color=#FFCF3B>\226\128\187 Der regenerierte Bishop erschafft in ihrer Ultimate-Phase vor\195\188bergehend einen unsterblichen Klon.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
