L51_1 = "Eine gewaltige Waffe unbekannter Herkunft aus einer anderen Dimension. Sie ist darauf spezialisiert, weit entfernte Feinde zu \195\188berw\195\164ltigen, und ist dank eines Antriebssystems, das dem eines Dimensionsschiffs \195\164hnelt, auch zu ungest\195\188tzten Dimensionsspr\195\188ngen f\195\164hig.\n\nSie k\195\182nnte urspr\195\188nglich programmiert worden sein, um zur Counterside und wieder zur\195\188ck zu reisen und C. O.s zu jagen, aber als sie entdeckt wurde, war sie bereits au\195\159er Kontrolle, da sie durch Verderbniswellen irreparabel besch\195\164digt worden war.\n\n<color=#FFCF3B>\226\128\187 Der Moderator erleidet zus\195\164tzlichen Schaden, wenn er von hinten angegriffen wird, wo er verwundbar ist.</color>"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_BOSS_DESC_01"
L52_1 = "Eine gewaltige Waffe unbekannter Herkunft aus einer anderen Dimension. Sie ist darauf spezialisiert, nahende Feinde zu pulverisieren, und ist dank eines Antriebssystems, das dem eines Dimensionsschiffs \195\164hnelt, auch zu ungest\195\188tzten Dimensionsspr\195\188ngen f\195\164hig.\n\nSie k\195\182nnte urspr\195\188nglich programmiert worden sein, um zur Counterside und wieder zur\195\188ck zu reisen und C. O.s zu jagen, aber als sie entdeckt wurde, war sie bereits au\195\159er Kontrolle, da sie durch Verderbniswellen irreparabel besch\195\164digt worden war.\n\n<color=#FFCF3B>\226\128\187 Der Moderator erleidet zus\195\164tzlichen Schaden, wenn er von hinten angegriffen wird, wo er verwundbar ist.</color>"
L50_1[1] = L51_1
L50_1[2] = L52_1
