L51_1 = "SI_SKIN_DESC_NKM_UNIT_C_HB_RUMI_FOOLSDAY"
L52_1 = "<color=#ffd34c>\226\128\187 Diese Skin \195\164ndert lediglich das Aussehen des Charakters. \226\128\187</color>\n\nHRT Berrys zweitbestes Mitglied aller Zeiten will zeigen, was sie kann. Also ruft jetzt alle lieber \226\128\158Lumi ist die Beste!\226\128\156, sonst d\195\188rft ihr in Zukunft alles doppelt machen\194\160\226\128\166\nSonst d\195\188rft ihr in Zukunft alles doppelt machen. Dazu werdet ihr n\195\164mlich dann verflucht.\n\n<color=#ffd34c>Moment mal! Alles, was die Managerin mir erz\195\164hlt hat, selbst Name und Beschreibung, ist das genaue Gegenteil!</color>"
L50_1[1] = L51_1
L50_1[2] = L52_1
