L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_SKIN_DESC_NKM_UNIT_C_BD_ROI_CHANGE"
L36_1 = "Schon geh\195\182rt? Ein interessanter Neuling ist in Prydwen ankommen.\nIhr K\195\182nnen ist noch nicht ausgereift, aber ihr Hygienebewusstsein soll makellos sein.\nUnd so jemand ist Sir Burnetts Enkelin ... Schon faszinierend.\nDem Boss scheint sie allerdings nicht wirklich zu gefallen ...\n\n<color=#ffd34c>Wie bitte? Das ist keine Zwangsneurose! Ich kann Dreckiges blo\195\159 nicht ausstehen!</color>"
L34_1[1] = L35_1
L34_1[2] = L36_1
