L4_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_UNIT_01_04"
L5_1 = "Damit alle Verb\195\188ndeten SDN-WDS-Buffs stapeln und Angriffen widerstehen, <COLOR=#FFBC00>sollten Sie vor allem auf Mitarbeiter zur\195\188ckgreifen, die SDN-WDS-Buffs verleihen</COLOR>."
