L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_DESC_01"
L50_1 = "Um einem Strategiekampf beizutreten, musst du zun\195\164chst einen <COLOR=#FFBC00>Verteidigungstrupp bilden</COLOR>.\nDein Verteidigungstrupp wehrt Angriffe anderer Unternehmen ab. Buffs sowie Verbannungen & Vorteile gelten f\195\188r sie.\nDu erh\195\164ltst jedes Mal <COLOR=#FFBC00>Fehdepunkte</COLOR>, wenn du einen Verteidigungskampf gewinnst.\nWenn du im Verteidigungskampf verlierst, werden dir Siegespunkte abgezogen und ab einer bestimmten Anzahl nicht mehr."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_TEXT_01_1"
L51_1 = "Einige Einheiten deines Verteidigungstrupps werden vor anderen geheim gehalten."
