L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_03"
L49_1 = "<COLOR=#FFBC00>2 Minuten vor Kampfende aktiviert sich das Ein\195\164scherungs-System und f\195\188gt allen Mitarbeitern au\195\159er jenen innerhalb des Schiffs einen hohen Schaden zu.</COLOR>\n\226\128\187 <COLOR=#FFBC00>Nach der Ein\195\164scherung wird dem Unterdr\195\188cker ein nicht entfernbarer Buff von SDN-WDS +80 % verliehen.</COLOR>"
