L49_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_04"
L50_1 = "Der Unterdr\195\188cker <COLOR=#FFBC00>feuert 35 Sekunden vor Kampfende einen Laser ab und f\195\188gt allen Mitarbeitern gro\195\159en SDN zu.</COLOR>\n\226\128\187 <COLOR=#FFBC00>Die Barriere eines Mitarbeiters, der SDN durch den Laser erleidet, wird entfernt.</COLOR>"
