L16_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_PIECE_UNIT_BAR_C_CEO"
L17_1 = "Ein Gegenstand, der diverse Informationen \195\188ber [Gremory] enth\195\164lt.\nSammle diese Gegenst\195\164nde, um den entsprechenden Charakter mithilfe von Scouting zu rekrutieren."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
