L20_1 = "SI_UNIT_SKILL_DESC_BAR_C_CEO_ATTACK_LV1"
L21_1 = "Feuert ihre Liebe ab (behauptet sie) und verursacht Schaden an ein Ziel vorne."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_UNIT_SKILL_DESC_BAR_C_CEO_HYPER_LV1"
L22_1 = "Dr\195\164ngt umliegende Feinde in ihre Blickrichtung und wirkt einen Effekt wie Partyzeit! auf und um ihr Ziel herum. Gremorys Ultimate-F\195\164higkeit ist immer auf 0 geladen, wenn sie eingesetzt wird."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_UNIT_SKILL_DESC_BAR_C_CEO_HYPER_LV5"
L23_1 = "Einsatzressourcen +1 pro Einsatz und beim Wirken von Ultimate"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_UNIT_SKILL_DESC_BAR_C_CEO_PASSIVE_LV1"
L24_1 = "Erzeugt einen \226\128\158fr\195\182hlichen Wasserstrahl\226\128\156 auf ihrem Einsatzort, der 6 Sekunden lang Schaden zuf\195\188gt. Davon getroffene Gegner werden f\195\188r 4 Sekunden in Schlaf versetzt (Bosse ausgenommen). Wirkt sich nur auf so viele Ziele aus, wie g\195\188ltige Treffer erzielt werden."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_UNIT_SKILL_DESC_BAR_C_CEO_PASSIVE_LV5"
