L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_EPILOGUE"
L49_1 = "Momo sagte, ein Geb\195\164ude sei explodiert, also bin ich ihr gefolgt. Wer h\195\164tte gedacht, dass es unser Laden w\195\164re? Ich kann Momos Gesichtsausdruck an diesem Tag nicht vergessen."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_1"
L50_1 = "Ich bin noch nicht lange hier, aber ich f\195\188hle mich, als w\195\164re ich schon ewig hier. Nat\195\188rlich wei\195\159 ich, dass das nicht ewig so bleiben kann."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_2"
L51_1 = "Ich habe mir versprochen, dass ich meine heilige Mission nicht aufgeben werde. Aber wie kommt es, dass ich immer wieder z\195\182gere? Vielleicht bin ich schon vom Teufel verf\195\188hrt worden."
L49_1[1] = L50_1
L49_1[2] = L51_1
