L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_INTRO_ORIGINAL"
L8_1 = "Je h\195\182her das Ideal, desto leichter f\195\164llt es, und je reiner das Herz, desto leichter wird es beschmutzt. Trotzdem ... habe ich nicht die Absicht, meine Liebe jetzt noch aufzugeben."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_CONNECT"
L9_1 = "Ach, du meine G\195\188te, wie s\195\188\195\159 Sie sind."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_CONNECT_LIFETIME"
L10_1 = "Der Grund, warum ein Schmetterling seine Fl\195\188gel in die weite Welt ausbreiten kann, ist die Liebe. Selbst wenn er dabei zu hoch hinauffliegt und sich seine Fl\195\188gel verbrennt, wird er gl\195\188cklich sein, wenn er es einem Geliebten zuliebe tut."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_1"
L11_1 = "Sagen Sie nur Bescheid, Boss. Was auch immer Ihr Wunsch ist, erf\195\188lle ich ihn gerne. Auch wenn es mich alles kostet."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_2"
L12_1 = "Ich erwarte nicht, dass andere mich verstehen. Auch wenn es verdreht und einseitig sein mag, haben Sie in mir diese Gef\195\188hle geweckt, Boss. Und es l\195\164sst sich gegen nichts tauschen."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_3"
L13_1 = "Ich habe dieses Outfit mit Ihrem Geschmack im Hinterkopf zusammengestellt. Wie finden Sie es? Hihi, vor mir m\195\188ssen Sie nicht so sch\195\188chtern sein. Ich kenne selbst die kleinsten Details \195\188ber Sie und ihren Geschmack."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_4"
L14_1 = "Wie f\195\188hlt es sich an, so durch den Nachthimmel zu streifen, nur wir beide? Sehen die St\195\164dte und Menschen nicht schwindend klein aus? Wenn Sie nur wollen ... sorge ich daf\195\188r, dass Ihnen all das geh\195\182rt."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_LIFETIME_1"
L15_1 = "Sie d\195\188rfen so freundlich zu anderen Mitarbeiterinnen sein, wie Sie m\195\182chten. Denn ich wei\195\159, dass Sie am Ende doch zu mir zur\195\188ckkommen, Boss. Hihihi."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
