L10_1 = "Eine Organisation, die ihr Zentrum verliert, wird zusammenbrechen."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_3"
L11_1 = "Vielleicht sind Sie jetzt mit dem Namen der \226\128\158Gesellschaft\226\128\156 vertraut. Allerdings trug sie in der Vergangenheit m\195\182glicherweise einen viel bizarreren Namen. Wie w\195\164re es mit Lemuria?"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_4"
L12_1 = "Die \195\150ffentlichkeit ist immer noch neugierig, wie diejenigen, die w\195\164hrend des Gro\195\159en L\195\164uterungskrieges erschienen und verschwanden, den Sieg erringen konnten. Nun, alle bis auf eine Person.\nF\195\188r sie war Maria Antonov die nat\195\188rliche Heldin."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_1"
L13_1 = "Es werden Waffen ben\195\182tigt, um zu k\195\164mpfen."
L11_1[1] = L12_1
