L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_2"
L14_1 = "Wenn Menschen in die Enge getrieben werden, hoffen sie auf ein Wunder."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_3"
L15_1 = "Die Schattenpal\195\164ste sind ein Raum, der die Klippa-Dimension und die Normalside verbindet. Je st\195\164rker der Einfluss der Klippa-Dimension ist, desto gr\195\182\195\159er ist die Gefahr."
L13_1[1] = L14_1
