L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_4"
L16_1 = "Eine Imitation aus einer Handvoll Resten, die mit Faden zusammengen\195\164ht und mit dem Evangelium gef\195\188llt sind."
