L3_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_CONNECT"
L4_1 = "Die Leute haben in der Regel mehr Albtr\195\164ume im Hochsommer. Haben Sie ... einen schlechten Traum gehabt?"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_CONNECT_LIFETIME"
L5_1 = "Vergessen Sie nicht Ihr Versprechen. Wenn ich Ihren Albtraum mitnehme, gehen Sie mit mir schwimmen."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_1"
L6_1 = "Kaltes Wasser und ein eisiger Albtraum. Ganz sch\195\182ne Kombination. Vielleicht schwimme ich deshalb auch gerne, oder nicht?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_2"
L7_1 = "Das ist das erste Mal ... Ich war so besch\195\164ftigt, Albtr\195\164ume loszuwerden, dass ich gar nicht gemerkt habe, wie ich meine F\195\188\195\159e eingetaucht habe. Es ist in Ordnung, sich ein bisschen zu entspannen, oder?"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_3"
L8_1 = "Gibt es etwas Hoffnungsloseres als das Spiegelbild des Mondes auf dem Wasser? Man versucht, daran festzuhalten, und es flie\195\159t dahin. So schade ... aber ich versuche es immer wieder, obwohl ich wei\195\159, dass es nicht geht."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_4"
L9_1 = "Diese Flamme wird nicht ausgehen, selbst wenn sie nass wird. Es ist n\195\164mlich ein Albtraum, der den Tr\195\164umer immer wieder st\195\182rte. Deshalb lasse ich ihn immer hoch am Himmel. So kann er ein kleines St\195\188ck des Himmels erhellen, wie ein Stern."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_1"
L10_1 = "Tr\195\164ume sind wie Wasser. Es f\195\188hlt sich an, als w\195\188rde man frei herumschwimmen. Aber ... genau wie im Wasser sp\195\188rt man diesen erstickenden Druck. Ich empfehle es also nicht wirklich."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_2"
L11_1 = "Ich trage zum ersten Mal einen Schwimmanzug ... wie finden Sie es? Gef\195\164llt er Ihnen? Jemand gab es mir vor dem Tod. Obwohl ich nicht wei\195\159, wer diese Person war ... k\195\182nnten Sie ihm oder ihr bitte sagen, dass ich Albtr\195\164ume fernhalten werde?"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_3"
L12_1 = "Ich mag es, meine F\195\188\195\159e ins Wasser zu tauchen. Es f\195\188hlt sich an, als w\195\188rde das Wasser an meinen F\195\188\195\159en kleben, wenn ich die Oberfl\195\164che ber\195\188hre, aber sobald ich hineintauche, f\195\188hlt es sich an, als w\195\188rde ich fallen. Genau dieses Gef\195\188hl m\195\182chte ich den Tr\195\164umern geben, wenn ich mich um einen Albtraum k\195\188mmere."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_4"
L13_1 = "Dies ist ein Albtraum, den ich von Ihnen gesammelt habe. K\195\182nnen Sie sehen, wie viel st\195\164rker und dunkler als die anderen Flammen er ist? Das liegt daran, dass Sie wie das Spiegelbild des Mondes auf dem Wasser hell scheinen."
L11_1[1] = L12_1
L11_1[2] = L13_1
