L34_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_02_03"
L35_1 = "Die <COLOR=#FFBC00>Spezialf\195\164higkeiten von Tyrannenriese \195\164ndern sich 2 Minuten vor Ende</COLOR> des Kampfes.\nBei Verwendung einer Spezialf\195\164higkeit wird die <COLOR=#FFBC00>Tyrannenpanzerung heraufbeschworen, um Gegner abzublocken, und ein m\195\164chtiger Sturmangriff wird vorbereitet</COLOR>.\nWenn dies nicht rechtzeitig gestoppt wird, <COLOR=#FFBC00>beginnt ein m\195\164chtiger Angriff in allen Bereichen</COLOR>."
L33_1[1] = L34_1
L33_1[2] = L35_1
