L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_3_INTERLUDE_3"
L47_1 = "Moment mal, hast du kurz Zeit? Ich muss dir was erz\195\164hlen."
