L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_3_INTERLUDE_1"
L49_1 = "Ich bin fr\195\188her als gew\195\182hnlich aufgewacht. Es war eine seltsame Schule."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_3_EPILOGUE_2"
L50_1 = "Erinnerungen sind fl\195\188chtig.\nIch kann mich nicht einmal an das Mittagessen erinnern, das ich gestern hatte, aber pl\195\182tzlich f\195\164llt mir eine Mahlzeit ein, die ich vor 10 Jahren mit meiner Familie gegessen habe."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_3_EPILOGUE_1"
L51_1 = "Es gibt zwei j\195\164hrliche Veranstaltungen, auf die sich die Sch\195\188ler der Akademie freuen.\nDie erste ist der Sporttag.\nUnd die zweite ... ist das Festival der Akademie."
L49_1[1] = L50_1
L49_1[2] = L51_1
