L23_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_CONNECT_LIFETIME"
L24_1 = "You're back. Let's do this together!"
