L12_1 = {}
L13_1 = "REACTOR_DESC_1097"
L14_1 = "Ein Hawkville-Messer, gestohlen von einem ber\195\188hmten S\195\182ldner. Wenn es f\195\188r ihre eigenen Zwecke ist, wird sie sich alles schnappen, ungeachtet der Mittel oder Methoden. Der Reaktor spiegelt die Akribie des Benutzers als Medium zur Leistungssteigerung wider."
L12_1[1] = L13_1
