L36_1 = "REACTOR_DESC_1072"
L37_1 = "Ein unbekanntes Langschwert. Das Schwert, das auf das CRS des Benutzers reagiert und rot wird, durchschneidet sogar unsichtbare Fl\195\188che. Der Reaktor spiegelte die Loyalit\195\164t gegen\195\188ber dem Anf\195\188hrer als Medium zur Leistungssteigerung wider."
L35_1[1] = L36_1
