L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_EMBLEM_BIRTHDAY"
L42_1 = "Ein von Mitarbeitern heimlich vorbereiteter Kuchen, um Ihren Geburtstag zu feiern.\nJeder hat etwas Geld gegeben, um ihn ganz nach seinen W\195\188nschen zubereiten zu lassen. Wer am meisten gezahlt hat, bleibt Ihrer Fantasie \195\188berlassen."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_PACKAGE_BIRTHDAY_BOX"
L43_1 = "Eine Kiste voller Gl\195\188ckw\195\188nsche zum Geburtstag.\nWenn du sie \195\182ffnest, kannst du verschiedenste Geschenke erhalten."
L41_1[1] = L42_1
