L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_SKIN_DESC_NKM_UNIT_KNIGHT_C_HOLY_MEMORIAL"
L52_1 = "Der Imperium Arcadena-Ball entstand aus der Anbetung Gottes.\nLoyalit\195\164t f\195\188r eine heilige Frau. Ein Schmuckst\195\188ck, das sie von einer geliebten Person erhalten hat.\nDer Glanz, der auch nach vielen Jahren nicht verblassen wird, wird sie zum Star des diesj\195\164hrigen Balls machen.\n\n<color=#ffd34c>Bitte stimmen Sie Ihre Bewegungen heute auf mich ab. Diesen Tanz habe ich mehrmals f\195\188r Sie ge\195\188bt.</color>"
L50_1[1] = L51_1
L50_1[2] = L52_1
