L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_UNIT_SKILL_DESC_JAPAN_C_CRAFTER_HYPER_LV1"
L13_1 = "Sammelt die Energie der Flamme im Hammer und gew\195\164hrt allen verb\195\188ndeten Counter-Einheiten auf dem Schlachtfeld, au\195\159er sich selbst, Nahkampfabwehr-SDN-WDS +60 % und Fernkampfabwehr-SDN-WDS +60 % (Beschworene ausgenommen). Dieser Effekt verringert sich alle 3 Sekunden um 10 % und verschwindet schlie\195\159lich. Schl\195\164gt dann den Hammer kr\195\164ftig nach unten und f\195\188gt Gegnern Fl\195\164chenschaden zu. Gegner, die Schaden erlitten haben, werden 4 Sekunden lang bet\195\164ubt\226\151\135."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
