L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_SKILL_DESC_JAPAN_C_CRAFTER_PASSIVE_LV1"
L15_1 = "Beim Wirken eines Standardangriffs wird der [H\195\164rten]-Modus gestapelt, der KRIT um 30 erh\195\182ht (bis zu 600). Wenn im [H\195\164rten]-Modus KRIT entsteht, wird zum [Angriffsbereit]-Modus gewechselt.\nVom [Angriffsbereit]-Modus wird nicht in den [H\195\164rten]-Modus gewechselt. Bei Angriffen wird der Cooldown der Spezialf\195\164higkeit um 4 Sekunden reduziert. Der Effekt wird beim Wirken der Spezialf\195\164higkeit aufgehoben."
L13_1[1] = L14_1
