L48_1 = "SI_PF_POPUP_EVENT_RACE_BETTING_TUTORIAL"
L49_1 = "<b><color=#4EC2F3>[Team-Staffel]</color></b>\n<color=#FFCF3B>\226\128\147 Du kannst eines der beiden Teams ausw\195\164hlen und es dann mit Event-Ressourcen anfeuern.</color>\n<color=#FFCF3B>\226\128\147 Wenn das von dir angefeuerte Team gewinnt, kannst du Ressourcen entsprechend der Belohnungsvergr\195\182\195\159erung erhalten.</color>\n<color=#FFCF3B>\226\128\147 Das Rennen findet einmal t\195\164glich statt. W\195\164hrend der Abrechnungszeiten werden keine Events durchgef\195\188hrt.</color>\n\n<b><color=#FFFFFF>[Rennmission]</color></b>\n<color=#F2F2F2>\226\128\147 Du kannst Event-Ressourcen erhalten, indem du die bereitgestellten Missionen abschlie\195\159t.</color>\n\n<b><color=#FFFFFF>[Anfeuern]</color></b>\n<color=#F2F2F2>\226\128\147 Du kannst die Event-Ressourcen nutzen, um das Team deiner Wahl anzufeuern.</color>\n<color=#F2F2F2>\226\128\147 Es kann nur ein Team pro Tag gew\195\164hlt werden.</color>\n<color=#F2F2F2>\226\128\147 Du kannst bis zu 500 Ressourcen pro Tag zum Anfeuern verwenden.</color>\n\n<b><color=#FFFFFF>[Belohnung]</color></b>\n<color=#F2F2F2>\226\128\147 Wenn das Team, das du angefeuert hast, gewinnt, werden die zum Anfeuern verwendeten Ressourcen entsprechend der Belohnungsvergr\195\182\195\159erung ausgezahlt.</color>\n<color=#F2F2F2>\226\128\147 Wenn das Team, das du angefeuert hast, verliert, werden 80 % der Ressourcen, die du zum Anfeuern verwendet hast, zur\195\188ckgegeben.</color>\n<color=#F2F2F2>\226\128\147 Du kannst deine Belohnungen zu Beginn des Rennens am n\195\164chsten Tag erhalten.</color>"
L47_1[1] = L48_1
L47_1[2] = L49_1
