L43_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DEFENCE_DUNGEON_BATTLE_06"
L44_1 = "Letzter Versuch \226\128\147 Saison 5"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_DEFENCE_BANNER_02_DESC_3"
L45_1 = "1. <b>Regelm\195\164\195\159iges Erscheinen von Gegnern:</b> M\195\164chtige Gegner tauchen regelm\195\164\195\159ig auf.\n\n2. <b>Erhalt von Killpunkten:</b> Wenn du ein Monster t\195\182test, erh\195\164ltst du Killpunkte.\n\n3. <b>Rangpriorit\195\164t:</b> Wenn die Killpunkte gleich sind, wird der Spieler, der zuerst in der Rangliste registriert wurde, h\195\182her eingestuft.\n\n4. <b>Erweiterter Einsatzbereich:</b> Der Einsatzbereich aller verb\195\188ndeten Einheiten wurde erweitert.\n\n5. <b>Gew\195\164hrung von Immunit\195\164t gegen Bet\195\164ubungstreffer:</b> Ab 2 Minuten nach Beginn des Kampfes wird allen gegnerischen Einheiten Immunit\195\164t gegen Bet\195\164ubungstreffer gew\195\164hrt.\n\n6. <b>Regeneration-VSL (erstes Mal):</b> Ab 2 Minuten und 30 Sekunden nach Beginn des Kampfes wird allen Einheiten Regeneration-VSL 60 % gew\195\164hrt.\n\n7. <b>ATMP-Erh\195\182hung:</b> Ab 3 Minuten nach Beginn des Kampfes erh\195\182ht sich das ATMP der gegnerischen Einheiten um 100 %.\n\n8. <b>Regeneration-VSL (zweites Mal):</b> Ab 3 Minuten und 30 Sekunden nach Beginn des Kampfes wird allen Einheiten Regeneration-VSL 80 % gew\195\164hrt.\n\n9. <b>SDN-Erh\195\182hung:</b> Ab 4 Minuten nach Beginn des Kampfes erh\195\182ht sich der Ausgeteilte SDN gegnerischer Einheiten um 100 %."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
