L35_1 = "SI_PF_EVENTMATCH_MAIN_MENU_RULE_PLAY_RULE_AUTO"
L36_1 = "Regeln\n\n\226\128\147 Manuelle Steuerung nicht m\195\182glich\n\226\128\147 Feste Einsatzreihenfolge\n\226\128\147 Verbannungen & Vorteile nicht angewandt\n\226\128\147 Ausr\195\188stungswerte werden angewandt"
