L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_PF_EVENTMATCH_MAIN_MENU_RULE_PLAY_SPELLCARD"
L4_1 = "Regeln\n\n\226\128\147 Ausr\195\188stungswerte werden angewandt\n\226\128\147 Verbannungen & Vorteile angewandt\n\n\226\128\147 Angriffspaket: ALPHA\nStarker Angriff, der die meisten Verteidigungsf\195\164higkeiten ignoriert\nWirkzeit: 4 s, enge Reichweite, Bodeneffekt\n\n\226\128\147 Angriffspaket: BRAVO\nAngriff, der die meisten Verteidigungsf\195\164higkeiten ignoriert\nWirkzeit: 0,5 s, normale Reichweite, Rundumeffekt\n12 s lang wird der Effekt [Nicht heilbar] innerhalb der Reichweite angewandt. Bei Einheiten, deren Kosten 3 oder weniger sind, werden die Verteidigungsf\195\164higkeit und alle Werte erheblich verringert"
L2_1[1] = L3_1
L2_1[2] = L4_1
