L7_1 = {}
L8_1 = "REACTOR_DESC_1071"
L9_1 = "Eine Form, in der der Wille einer von der Welt auserw\195\164hlten Person zum Ausdruck gebracht wird, um den Feinden entgegenzutreten, die die Welt bedrohen. Konzentriert die einzigartige Wellenform, um Feinde zu vernichten. Der Reaktor spiegelt den Willen des Benutzers, die Welt zu sch\195\188tzen, als Medium zur Leistungssteigerung wider."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "REACTOR_DESC_1193"
L10_1 = "Ein Koffer, der die Telepathief\195\164higkeiten unterst\195\188tzt. Er l\195\164sst die CRS des Benutzers resonieren und verbreitet sie, um sie an Partner weiterzugeben. Der Reaktor spiegelt die Empathie des Benutzers als Medium zur Leistungssteigerung wider."
L8_1[1] = L9_1
L8_1[2] = L10_1
