L20_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_GET_01"
L21_1 = "Ich habe auf dich gewartet. Einige Teufel, die es auf deine Seele abgesehen haben, waren hinter dir her. Ich habe mich darum gek\195\188mmert, also sei bitte nicht mehr allein unterwegs und bleib in meiner N\195\164he."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_CAPTAIN"
L22_1 = "Sprich. Ich werde dir zuh\195\182ren."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_CONNECT"
L23_1 = "Folge mir. Es gibt einen Ort, zu dem wir gehen m\195\188ssen."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_CONNECT_LIFETIME"
L24_1 = "Du bist wach. Ich habe auf dich gewartet."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_1"
L25_1 = "Diese Stille mag ich zwar, aber manchmal vermisse ich den Klang der Musik. ... Du willst f\195\188r mich ein Saiteninstrument lernen? Es ist bewundernswert, dass du diese Entscheidung getroffen hast, aber achte darauf, dass du dir nicht die Finger verletzt."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_2"
L26_1 = "Du bist mein einziger Anh\195\164nger. Dein Leben ist eins mit meinem, also sei nicht leichtsinnig."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_3"
L27_1 = "Wahren Glauben zu haben, bedeutet, nicht zu z\195\182gern, Opfer zu bringen. Ich bin bereit, alles zu geben, um deinen Glauben zu gewinnen, selbst mein Leben."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_4"
L28_1 = "Fr\195\188her dienten mir unz\195\164hlige Menschen des Ordens. Aber jetzt brauche ich keine anderen Anh\195\164nger als dich. Selbst wenn die Welt zusammenbricht, wirst du der Einzige sein, den ich besch\195\188tze."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_LIFETIME_1"
L29_1 = "Eine Blume? F\195\188r mich? ... Danke. Aber geh aus solchen Gr\195\188nden nicht ohne meine Erlaubnis irgendwo hin. Ich kann es nicht riskieren, dich wegen einer einzigen Blume zu verlieren."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_LIFETIME_2"
L30_1 = "Hast du allein ein Instrument ge\195\188bt? \195\156berfordere dich nicht zu sehr. Denn was ich h\195\182ren m\195\182chte, ist keine verf\195\188hrerische Melodie, sondern deine Stimme."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_LIFETIME_3"
L31_1 = "Wenn ich mich zwischen der Welt und deinem Leben entscheiden m\195\188sste, w\195\188rde ich mich ohne zu z\195\182gern f\195\188r dich entscheiden. Vielleicht verliere ich dadurch alles, aber meine Waage wird nie auf die andere Seite kippen."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_LIFETIME_4"
L32_1 = "Selbst wenn ich alleine k\195\164mpfen m\195\188sste, w\195\188rde ich dich nicht zu meinem Apostel machen. Alles, was ich von dir will, ist dein Glaube. Ich habe nicht die Absicht, dich in Gefahr zu bringen."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_WORLDMAP_CHECK"
L33_1 = "Die Stille h\195\164lt an. Gut."
L31_1[1] = L32_1
L31_1[2] = L33_1
