L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_2_1"
L26_1 = "I've never forgotten the reason I wander through the damned Counterside."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
