L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE3"
L48_1 = "Culkin is a capable manager, but he's too naive to be in this line of work. But that's also why I trust him."
