L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE4"
L49_1 = "Edwin Freeheart. I need to find that man."
L47_1[1] = L48_1
L47_1[2] = L49_1
