L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_GET_01"
L8_1 = "My name is Yanikka Shirokova. As you can see, I'm a mixed beauty with cute fangs! Please call me Yanikka! You can put me to work right away! I'll do anything!"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_CAPTAIN"
L9_1 = "Yes, feel free to put me to work!"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_CONNECT"
L10_1 = "Hello! Is there anything you want me to do?"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_CONNECT_LIFETIME"
L11_1 = "You saw me as soon as you checked in! Congratulations! I hope your day is as bright as my smile!"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_NORMAL_1"
L12_1 = "You see, I get so absorbed in a fight that sometimes my tone changes a bit. Eheheh. Just letting you know so you don't get surprised."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_NORMAL_2"
L13_1 = "I always have perfume with me wherever I go. The woody ambrette scent makes the smell of blood on my skin especially alluring."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_NORMAL_3"
L14_1 = "I've been through some tough battles, so I know basic first aid. I'm especially good at stopping bleeds, so if there's anyone bleeding out, be sure to come to me. I mean it!"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_NORMAL_4"
L15_1 = "It's a tiring stereotype to think that combatants don't care about their appearances. Think about it from the enemy's perspective. Wouldn't you hesitate to pull the trigger if you were fighting a cutie? That's when you strike first!"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_LIFETIME_1"
L16_1 = "Making a bullet hole is nice and all, but my aim is terrible. Plus, sucking on a bullet hole is a real eyesore, no?"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_LIFETIME_2"
L17_1 = "Oh, is it time to eat? Please, go ahead without me. I'm embarrassed to eat in front of others. And I'll get really red and flustered if you peek. So no looking!"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_LIFETIME_3"
L18_1 = "You meet all sorts of people during missions. Some freak out and call a lady like me a pervert... I mean, one can end up with a rough manner of speech when doing rough jobs. Don't you think so?"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_LOBBY_TOUCH_LIFETIME_4"
L19_1 = "Please feel free to use me as a meat shield when things get dangerous. Ah hah hah, grudges? Don't worry about it. In fact, it actually feels good! Ah... forget what I just said. Teehee!"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
