L18_1 = {}
L19_1 = "SI_UNIT_SKILL_DESC_SHARKS_C_CANNON_PASSIVE_LV1"
L20_1 = "Alle Angriffe von Tallie verwenden speziell modifizierte Kugeln, die mehrfach explodieren. Nach 6 Standardangriffen repariert sie ihren \195\188berhitzten Gewehrlauf, um einen verbesserten Angriff auszuf\195\188hren, der Funken freisetzt."
