L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_SKILL_DESC_SHARKS_C_CANNON_HYPER_LV1"
L21_1 = "Springt in die Luft und feuert eine spezielle Kugel ab, die dem Ziel und seiner Umgebung Fl\195\164chenschaden zuf\195\188gt. Sie vergisst auch nie, die Explosion f\195\188r den Ruf der Sharks aufzupeppen."
L19_1[1] = L20_1
L19_1[2] = L21_1
