L21_1 = "SI_UNIT_SKILL_DESC_SHARKS_C_CANNON_ATTACK_LV1"
L22_1 = "Feuert ihren Romantikmacher ab, um Gegnern vor sich Fl\195\164chenschaden zuzuf\195\188gen."
