L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_BOSS_DESC_S3_01"
L25_1 = "Ein gro\195\159es C.\194\160O., das wahllos alles zerst\195\182rt und verschlingt und starke Verderbniswellen aussendet, die die Counterside herbeirufen.\nEs wird angenommen, dass es im imagin\195\164ren Raum schwimmt, und wenn es auftaucht, verwandelt es die Dimension in eine zerst\195\182rte W\195\188stenstadt.\nEs scheint intelligent zu sein, da es durch Illusionen und Halluzinationen kommuniziert. Es nutzt Feuerkraft, indem es beispielsweise Strahlen aus verschiedenen Waffen des Schiffes schie\195\159t."
L23_1[1] = L24_1
L23_1[2] = L25_1
