L27_1 = {}
L28_1 = "SI_PF_RECALL_POPUP_SUBTITLE"
L29_1 = "Wenn du den ausgew\195\164hlten Mitarbeiter zur\195\188ckrufst, erh\195\164ltst du die f\195\188r sein Wachstum verwendeten Ressourcen sofort zur\195\188ck. Die Ausr\195\188stung des Mitarbeiters wird in dein Lager zur\195\188ckgebracht.\nEr wird durch denselben Mitarbeiter auf <color=#ffcf3b>Stufe 1</color> ersetzt, wobei die Anzahl der Auswahlm\195\182glichkeiten f\195\188r Ersatzmitarbeiter entsprechend der Stufe des Taktischen Updates erh\195\182ht wird."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
