L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_GET_01"
L42_1 = "Greetings to you, Administrator. I am Fatima Jamil, a Counter from Lotus. Could you please sign this for me? No, it is not a document that needs your approval, but for personal use."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_CAPTAIN"
L43_1 = "I will follow your orders, Administrator."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_CONNECT"
L44_1 = "You're back."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_CONNECT_LIFETIME"
L45_1 = "Let's go. My men are waiting for you."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_NORMAL_1"
L46_1 = "There is no name for my fighting skills. I have mastered all the well-known martial arts, but none of them suited my abilities. Hmm... If I had to name it, how does Ice Fist sound?"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_NORMAL_2"
L47_1 = "The lawless area of Lotus' outskirts is flooded with trash. So I go out to clean the streets with my men every weekend. Mm? No. I do not clean up the streets with my fist."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_NORMAL_3"
L48_1 = "If you are in trouble with all the restaurants being closed, then I shall treat you to a dish I learned from a hotelier not too long ago. I just happened to go grocery shopping yesterday and have lots of fresh ingredients."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_NORMAL_4"
L49_1 = "It's natural for you to be respected, Administrator. It is no easy task gaining the trust of many from behind the scenes. I, too, would like to be like you."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_LIFETIME_1"
L50_1 = "Who would I save if you and Senior were both drowning...? What a difficult question to answer. But both will be in danger if I hesitate. I will have to hope that Senior Isolde will be safe while I rescue you first, Administrator."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_LIFETIME_2"
L51_1 = "During my school days, I often helped my uncle with his business. I helped distribute rations to the people in the refugee zones. Many of my men who follow me today are ones that I met back then."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE@AB_UI_UNIT_VOICE_NKM_UNIT_LOTUS_C_KNUCKLE_LOBBY_TOUCH_LIFETIME_3"
L52_1 = "I am writing down everything you say and do, Administrator. I believe it will be a loss to humanity for your accomplishments to be forgotten simply because they are not noticeable."
L50_1[1] = L51_1
L50_1[2] = L52_1
