L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_SKIN_DESC_NKM_UNIT_CA_YOO_MI_NA_SPECIAL"
L43_1 = "Das Ende der Welt. In einer Welt, in der sogar die Zeit stehen geblieben ist.\nW\195\164hrend des langen Winters w\195\164rmt ihr euch an der K\195\182rperw\195\164rme des anderen.\nIhr versprecht, euch dem harten Schicksal zu stellen.\nDenn sie ist dein Wolf. Und du bist ihr Herr.\nF\195\188reinander seid ihr unersetzlich.\n\n<color=#ffd34c>Beim \195\156berleben geht es nicht darum, stark zu sein. \195\156berleben bedeutet stark zu sein.</color>"
L41_1[1] = L42_1
L41_1[2] = L43_1
