L20_1 = "SI_UNIT_SKILL_DESC_C_HB_GAEUN_RA_HYPER_LV1"
L21_1 = "Uuund wir sind LIVE! F\195\188hrt einen Komboangriff auf vordere und hintere Reihen aus, um das Herz der Zuschauer zu stehlen. F\195\188gt im Anschluss vielen Gegnern Schaden zu, indem sie im Blitzschritt eine Energiebombe platziert, die Fl\195\164chenschaden anrichtet (leichter R\195\188cksto\195\159, leichtes \226\128\158in der Luft\226\128\156)."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_UNIT_SKILL_DESC_C_JAPAN_SETSUNA_RA_SKILL_LV1"
L22_1 = "Ruft einen Windsto\195\159 herbei, der die LP aller Verb\195\188ndeten um 15 % und die eigenen um die H\195\164lfte wiederherstellt. F\195\188gt Gegnern Fl\195\164chenschaden zu (leichter R\195\188cksto\195\159, leichtes \226\128\158in der Luft\226\128\156)."
L20_1[1] = L21_1
