L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_GET_01"
L11_1 = "Hello...! This is Noelle Wright, your newly evolved Super Elite Rookie Squad Member, reporting in to Boss! Hehe...!"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_CAPTAIN"
L12_1 = "Of course! I'm your guardian angel, remember?"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_CONNECT"
L13_1 = "Boss, the morning air feels amazing today! Want to take a flight with me?"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_CONNECT_LIFETIME"
L14_1 = "Boss! What should we start with today? Neighborhood patrol? Organizing supplies...? Just say the word!"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_TOUCH_NORMAL_1"
L15_1 = "Hehehe! I'm not just Noelle anymore. I'm Super Elite Rookie Squad Member Noelle... or just Super Noelle for short! Whatever it is, leave it to me! I'll take care of it super quickly! Hup!"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_TOUCH_NORMAL_2"
L16_1 = "The biggest pair of wings I've got were made to look like my angel's! I can't fly with just my own wings yet... Oh! That's right! Want to try flying, Boss? I'll carry you!"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_TOUCH_NORMAL_3"
L17_1 = "My angel told me everything in this world is already decided... but that's okay. Choosing to accept that fate is still my choice! Hehe, and of course, choosing to support you, Boss, is my choice too!"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_TOUCH_NORMAL_4"
