L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_OPR_GRACE@AB_UI_UNIT_VOICE_OPR_GRACE_LOBBY_CAPTAIN"
L42_1 = "Conflict naturally subsides in the presence of a wise ruler."
L40_1[1] = L41_1
L40_1[2] = L42_1
