L28_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_GET_01"
L29_1 = "I can't believe the day would come when I'd wear this damn maid uniform again. *Sigh* Better not be for something petty. I charge a hefty service fee, you know."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_CAPTAIN"
L30_1 = "What? \"Master...?\" Yeah, right. Just be content with \"Coach,\" will you...?"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_CONNECT"
L31_1 = "Oh, you showed up. Don't tell me you were expecting a warm welcome."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_CONNECT_LIFETIME"
L32_1 = "Persistent, aren't you? Fine, welcome back, Master...! Happy now...?!"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_NORMAL_1"
L33_1 = "I thought that pervy hag was the only one obsessed with maids... So? Don't tell me you had me dress like this just to run errands."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_NORMAL_2"
L34_1 = "I don't care why all those Mansion freaks are so obsessed with maid uniforms, but... Tch, firing guns in a dress covered in frills and ribbons is extremely embarrassing."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_NORMAL_3"
L35_1 = "The design may look like this... but they say the suit's actually based on a space suit. Well, if you've got a goal, it doesn't matter whether it's in space or the Counterside. Once you start, you see it through."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_NORMAL_4"
L36_1 = "After seeing me like this, Skinner suggested making maid uniforms the theme for the next League team... Seriously, what does everyone think of my embarrassing past? What's so \"cute\" about this, anyway?"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_LIFETIME_1"
L37_1 = "Sure, housework is part of a maid's job. But come on, you know that's not my thing. I could make you a bowl of my signature cup noodles. Expect a service fee, of course."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_LIFETIME_2"
L38_1 = "So? How does it feel, playing master? You happy now? *Sigh* Well, consider it an honor. You're the only one in this world who could ever tame me."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_LIFETIME_3"
L39_1 = "F\195\169licette always took points in the Gauntlet, but switching roles was surprisingly refreshing. What do you think, Master? Maybe it's time we swapped roles in our relationship too?"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_ASSAULT_PR_LOBBY_TOUCH_LIFETIME_4"
L40_1 = "Don't tell me you're trying to walk away now after digging through my entire humiliating past? You know too much now. Whether you like it or not, you're stuck with me till the end, Master!"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
