L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP13_4_1"
L41_1 = "Gut ausgearbeitete Charaktere durchbrechen manchmal die Wand zwischen B\195\188hne und Publikum."
L39_1[1] = L40_1
L39_1[2] = L41_1
