L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP13_4_2"
L43_1 = "Wenn alle Schicksale an einem Punkt zusammentreffen,\nwiederholt sich die strahlend wei\195\159e Vernichtung, die die Welt \195\188berzieht."
L41_1[1] = L42_1
L41_1[2] = L43_1
