L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP13_4_3"
L45_1 = "Alles l\195\164uft nach Drehbuch. Dies ist das finale Ende, das ich vorbereitet habe."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP13_ACT4_INTERLUDE_3"
L46_1 = "Vielleicht habe ich die ganze Zeit gez\195\182gert.\nVielleicht habe ich es die ganze Zeit bereut.\nUnd vielleicht ist genau jetzt der Moment, die Wahrheit zu sagen, die ich nie aussprechen konnte."
L44_1[1] = L45_1
L44_1[2] = L46_1
