L49_1 = "The Law of Creating a World"
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP13_4_5"
L50_1 = "Dieses Drehbuch erz\195\164hlt die Geschichte eines M\195\164dchens, das einst ein Clown war \226\128\147 und schlie\195\159lich eine eigene Welt betritt."
L48_1[1] = L49_1
L48_1[2] = L50_1
