L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_ITEM_DESC_IQI_EQUIP_CORRUPTED_CA_MINISTRA_ACC_A"
L5_1 = "Dieses Herz wurde von jemandem verschmutzt, gesch\195\164rft und in eine leere Stelle gesetzt."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_ITEM_DESC_IQI_EQUIP_CORRUPTED_CA_MINISTRA_ACC_B"
L6_1 = "Ich habe alles f\195\188r meine Familie gegeben, doch zur\195\188ck blieb nur Leere. Zusammen mit einer Sehnsucht, die ich niemandem anvertraut habe."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_ITEM_DESC_IQI_EQUIP_CORRUPTED_CA_MINISTRA_DEFENCE"
L7_1 = "Meistens werden Ketten benutzt, um etwas einzusperren, doch ihre Gef\195\188hle wurden von der Einsamkeit gefangen gehalten."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_ITEM_DESC_IQI_EQUIP_CORRUPTED_CA_MINISTRA_WEAPON"
L8_1 = "Scharfer Stahl, neu geschmiedet von der Hand des Schattens. Jeder Schmerz und Schrei, hiervon verursacht, ist Teil des Prozesses der Neuordnung."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_SHADE_1_2_HM"
L9_1 = "Widerstand 2"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_2_HM"
L10_1 = "Auch wenn es ein Fl\195\188stern der Zerst\195\182rung ist, das Hoffnung verspricht \226\128\147 wenn ich dich in diesem Moment retten kann ..."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_ITEM_MISC_NAME_IMI_ITEM_USERTITLE_1500341"
L11_1 = "Titel: Schwarzer Schwan"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_ITEM_USERTITLE_NAME_1500341"
L12_1 = "Schwarzer Schwan"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_SKIN_DESC_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL"
L13_1 = "Bis zum Zeitpunkt, als der schwarze Schwan entdeckt wurde, zweifelte niemand daran, dass Schw\195\164ne wei\195\159 sind.\nErst als seine wahre Gestalt offenbar wurde, mussten die Menschen die Existenz des schwarzen Schwans anerkennen.\nAls sie diese Wahrheit erkannte, suchte sie wohl lange Zeit nur nach der einen Person.\nJemand jenseits ferner Welten, der erste, der ihr wahres Herz erkannte.\nDas warst du ...\n\n<color=#ffd34c>Und schlie\195\159lich lebten alle gl\195\188cklich bis ans Ende ihrer Tage. Kitschig, aber manchmal ist so ein Ende eben auch in Ordnung, oder?</color>"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_SKIN_TITLE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL"
L14_1 = "Schwarzer Schwan"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_NAME_SIXWING_CA_ACTOR_SPECIAL_SKILL_TROPHY"
L15_1 = "Swan Claire: Schwarzer Schwan"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_GET_01"
L16_1 = "They say the Black Swan always defies expectations. With this bond, I hope I can finally share my true feelings with you..."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_CAPTAIN"
L17_1 = "Your tie is a bit off, hmm. There, perfect now."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_CONNECT"
L18_1 = "As expected, this look is... a little embarrassing..."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_CONNECT_LIFETIME"
L19_1 = "I didn't expect... that simply linking arms could make my heart race like this..."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_1"
L20_1 = "The guests' gazes are sharp... I'm used to it, but I worry they may trouble you. Even so, I won't let go of your hand. I've become... a bit greedy, you see\226\128\166"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_2"
L21_1 = "In Swan Lake, one ballerina plays both Odette and Odile. This dress was designed after the Black Swan. That's because it's closer to the reflection of my true heart..."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_3"
L22_1 = "They say that even the most miraculous of chances is bound to happen if it's meant to be. So this oath, forged across countless worlds, will surely lead to a happy ending."
L20_1[1] = L21_1
L20_1[2] = L22_1
