L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_1"
L15_1 = "I used to see the Star Armament as nothing more than a symbol of the Order. But now, I understand. What I've inherited isn't just a sword. It's the pride of every knight who's wielded it before me."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_2"
L16_1 = "Whatever you seek, I will pursue. Whatever you desire, I will fight to obtain. I am your sword and shield. Everything I am is yours."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_3"
L17_1 = "The Red Shift situation has shaken the Order a bit, but it's all right. Deputy and others seem more motivated than ever, and with Dame Medea and Juli... ahem. Dame Leonhardt lending their strength, we'll be fine."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_4"
L18_1 = "The previous generation of the Zodiac Knights truly lived up to what people call the \"golden era.\" It's true that we, the current generation, fall short by comparison. But we have no intention of staying in their shadow forever."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_LIFETIME_1"
L19_1 = "I know that unleashing the Armament reflects the wielder's desires... B-but that doesn't mean I was imagining any specific outfit. An animal-themed pajama just happened to cross my mind by total coincidence."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_LIFETIME_2"
L20_1 = "I've carefully kept the sword and robe I used during my time of wandering. They're not hidden away, so Dame Liv or Dame Arius sometimes play around with them. When I see that... I find myself smiling the way she used to."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_LIFETIME_3"
L21_1 = "Sometimes I wonder, maybe I do long for a warm, peaceful family of my own. If I could build something like they had, my partner would be... no, forget it. That sort of future feels far too distant for me right now."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
