L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_CONNECT_LIFETIME"
L20_1 = "Looks like the guest of honor has arrived for the banquet."
