L40_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CLOUD_WEAPON"
L41_1 = "Es war einst zerbrochen, doch wuchs es von selbst \226\128\147 den Lauf der Dinge missachtend \226\128\147 wieder heran."
