L3_1 = "SI_UNIT_DESC_NKM_UNIT_ADMIN_CA_CLOUD"
L4_1 = "Ein Schl\195\164gertyp, der durch Bereich-Buffs Verb\195\188ndete unterst\195\188tzt und zus\195\164tzlichen Schaden an Feinden verursacht."
