L6_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_PASSIVE_LV1"
L7_1 = "Wird permanent immun gegen die Bet\195\164ubungstreffer von Spezialf\195\164higkeiten oder niedriger. Nach 5 Treffern erh\195\182ht sich der Schaden von verbesserten Angriffen um 25 % (bis zu 100 %). Alle 8 Sekunden wird automatisch ein verbesserter Angriff ausgef\195\188hrt, der festen Fl\195\164chenschaden nach vorne verursacht. Nach dem Einsatz eines verbesserten Angriffs wird der erh\195\182hte Schaden zur\195\188ckgesetzt und eine Barriere erzeugt, die 10 Sekunden lang 30 % der max. LP absorbiert."
L5_1[1] = L6_1
L5_1[2] = L7_1
