L7_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_PASSIVE_LV5"
L8_1 = "Immunit\195\164t gegen Erh\195\182hung des F\195\164higkeiten-Cooldowns. Nach dem Einsatz eines verbesserten Angriffs wird der Angriff permanent um 20 % erh\195\182ht (max. 8 Stapelungen)."
L6_1[1] = L7_1
L6_1[2] = L8_1
