L9_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_SKILL_LV1"
L10_1 = "Erzeugt ein Feld vorne. Innerhalb des Feldes ist sie gegen Bet\195\164ubung\226\151\135 immun und gew\195\164hrt sich selbst sowie verb\195\188ndeten Verteidigern und Vorhutk\195\164mpfern 30 % SDN-Dezimierung (nicht entfernbar). Gegner im Feld erleiden bei einem Treffer durch Yeonhwa zus\195\164tzlichen Schaden als \195\132quivalent zu Spezialf\195\164higkeiten. Stirbt Yeonhwa, verschwinden alle verbleibenden Felder auf dem Schlachtfeld."
L8_1[1] = L9_1
L8_1[2] = L10_1
