L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_PROLOGUE1"
L30_1 = "Ich habe nie dar\195\188ber nachgedacht, ob es gut oder schlecht ist, die Vergangenheit zu vergessen und weiterzuleben. Ich erinnere mich nur daran, dass es meine eigene Entscheidung war."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_1"
L31_1 = "Ein Albtraum, der aus der Tiefe emporsteigt und wiederaufersteht. Das flie\195\159ende Blut der Bestien ..."
L29_1[1] = L30_1
L29_1[2] = L31_1
