L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_1"
L33_1 = "Katastrophen sind f\195\188r alle schrecklich \226\128\147 nicht nur f\195\188r die, die dabei umgekommen sind, sondern auch f\195\188r die, die dabei zur\195\188ckbleiben."
