L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_2"
L36_1 = "Mitarbeiter, die die Administration verlassen, durchlaufen ein Verfahren, bei dem alle Erinnerungen an ihre Zeit dort gel\195\182scht werden. Angesichts der m\195\182glichen Folgen dieser Erinnerungen ist dies eine Ma\195\159nahme, die sowohl der Administration als auch der betreffenden Person dient."
