L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_3"
L39_1 = "Das Verbergen der Augen ist ein Symbol der Geheimnisvollheit. Masken, Augenklappen und Pony geh\195\182ren dazu."
