L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_4"
L42_1 = "Sie durchschneidet den Raum mit ihrem Schwert. Je nach F\195\164higkeit kann sie nicht nur Gegner zerschneiden, sondern auch Gegenst\195\164nde verstecken und Menschen transportieren."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_5"
L43_1 = "Die Administration entwickelte nach dem Gro\195\159en S\195\164uberungskrieg Strategien zur Wiederaufbau einer verw\195\188steten Welt. Viele Menschen kooperierten mit der Administration, getrieben von der einzigen Hoffnung."
L41_1[1] = L42_1
L41_1[2] = L43_1
