L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT2_INTERLUDE_2"
L47_1 = "Wie ein Tiger, der \195\188ber H\195\188gel springt, so durchschreiten sie die Zeiten. Um zu verhindern, dass diese Existenz das Heute erreicht, hat die Administration einen genialen Gelehrten angeworben \226\128\147 vom Schicksal dazu bestimmt."
