L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_5_1"
L30_1 = "Es gibt aufstrebende Sterne in der S\195\182ldnerbranche. Interessanterweise nehmen sie ausschlie\195\159lich Abbau-Missionen an."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT5_EPILOGUE_1"
L31_1 = "Vor Kurzem wurde in der Stadt ein neues Umweltmanagementsystem installiert. Die Administration k\195\188ndigte eine Feier zur Einweihung an."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT5_EPILOGUE_2"
L32_1 = "Schlie\195\159lich der gl\195\188cklichste Moment \226\128\147 und die darauf folgende Trag\195\182die."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
