L47_1 = "SI_SKIN_DESC_NKM_UNIT_VARUNA_C_WIND_SUMMER"
L48_1 = "Blaues Meer und klarer Himmel.\nEin perfekter Tag f\195\188r einen Workshop.\nEs ist immer eine Freude, Leute anzuleiten, die vor Aufregung kaum stillstehen k\195\182nnen.\nEndlich beginnt die freie Zeit! Vielleicht kann auch die Leiterin sich eine wohlverdiente Pause g\195\182nnen.\n\n<color=#ffd34c>Dieses Urlaubsparadies ist bekannt f\195\188r seine erfrischende Meeresbrise. M\195\182chten Sie sie sp\195\188ren?</color>"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_SKIN_TITLE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER"
L49_1 = "Goldener Sommer"
