L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_SKIN_DESC_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER"
L51_1 = "Es war als geheime Besprechung angek\195\188ndigt \226\128\147 aber in Wahrheit nur ein Vorwand f\195\188r eine kleine Auszeit.\nAls du auf der Insel ankamst, auf die du eingeladen wurdest, war sie bereits eingeschlafen, begleitet vom Rauschen der Wellen als Schlaflied.\nF\195\188r einen Ort der Zweisamkeit sind die beobachtenden Blicke doch etwas zu k\195\188hl ...\nAber was soll's? Ohne eine gewisse Entschlossenheit w\195\164re es ohnehin schwer gewesen, sie \195\188berhaupt zu treffen.\n\n<color=#ffd34c>So wie Sie mich anstarren, scheine ich wohl ganz Ihrem Geschmack zu entsprechen, oder?</color>"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_GET_01"
L52_1 = "I accepted your invitation. Now it's your turn. It's rare for me to take time off, so would you indulge me?"
L50_1[1] = L51_1
L50_1[2] = L52_1
