L4_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_CONNECT_LIFETIME"
