L5_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_1"
L6_1 = "It's good to feel the heat of the sun sometimes. Stay in the shade too long, and you forget how precious it is. Was I comparing sunlight to freedom? Did I really seem that rigid to you?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_2"
L7_1 = "I was reading an interesting book. Want to take a look? Haha, you thought I came all this way just to read political commentaries? No. It's about becoming a more sensual woman."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_3"
L8_1 = "I don't particularly enjoy getting wet. I'd rather not catch a cold. That look... you're wondering if someone cold-blooded like me can even get sick, aren't you? Haha. Even demons who set traps sometimes fall into their own."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_4"
L9_1 = "If El Dorado existed, I'd want to visit. Gold? I don't care for that. I'd want to collect the rare monsters that live only there. I suppose the desire comes from knowing they don't exist. Like mermaids or <color=#83dcb7>angels</color>."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_LIFETIME_1"
L10_1 = "Most things in this world are frightening because we don't understand them. Like the boogeyman in the closet or the witch in the woods. That's why you intrigue me. I've peeled back every layer of you, and yet I still revere what I find."
L8_1[1] = L9_1
L8_1[2] = L10_1
