L42_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_VARUNA_C_WIND_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_VARUNA_C_WIND_LOBBY_TOUCH_LIFETIME_2"
L43_1 = "The sun's a bit strong today. Hmm? Y-you want to put some oil on me? Ahaha... That's a little embarrassing... M-maybe we should, um... m-move over there? Somewhere a bit more private...?"
