L50_1 = {}
L51_1 = "SI_EXPLORE_RULE_1"
L52_1 = "<b><color=#FFD34C>[Gro\195\159expedition]</color></b>\n<color=#FFFFFF>\226\128\147 Spielbar nur w\195\164hrend des Eventzeitraums. Nach Ende des Events wird der Fortschritt zur\195\188ckgesetzt.</color>\n<color=#FFFFFF>\226\128\147 Statt deiner bestehenden Einheiten nutzt du neue Trupps, die du w\195\164hrend der Expedition erh\195\164ltst.</color>\n<color=#FFFFFF>\226\128\147 In jedem Abschnitt kannst du die Belohnungen und die Rollen der gegnerischen Einheiten einsehen. Nutze ihre Schw\195\164chen, um weiter vorzur\195\188cken!</color>\n<color=#FFFFFF>\226\128\147 Nach Erfolg oder Misserfolg einer Expedition werden alle w\195\164hrenddessen erhaltenen Trupps und Artefakte zur\195\188ckgesetzt.</color>\n\n<b><color=#FFD34C>[Saisonverbesserung der Gro\195\159expedition]</color></b>\n<color=#FFFFFF>\226\128\147 Wenn du eine Expedition abschlie\195\159t oder scheiterst, erh\195\164ltst du je nach Gebiet Verst\195\164rkungspunkte.</color>\n<color=#FFFFFF>\226\128\147 Mit diesen Punkten kannst du Saisonverbesserungen durchf\195\188hren. Verbesserte Werte k\195\182nnen jederzeit zur\195\188ckgesetzt werden.</color>\n\n<b><color=#FFD34C>[Punktbelohnungen der Gro\195\159expedition]</color></b>\n<color=#FFFFFF>\226\128\147 W\195\164hrend des Eventzweitraums erh\195\164ltst du Punkte, basierend auf der h\195\182chsten erstmals abgeschlossenen Stufe.</color>\n<color=#FFFFFF>\226\128\147 Mit den gesammelten Punkten kannst du zus\195\164tzliche Belohnungen erhalten.</color>"
L50_1[1] = L51_1
L50_1[2] = L52_1
