L2_1 = {}
L3_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_UNIT_GET_1"
L4_1 = "\195\156berlebende mitnehmen"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_UNIT_SKIP_1"
