L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EXPLORE_EVENT_MAIN_DESC_2"
L6_1 = "Als du dich der verlassenen Mine n\195\164herst, st\195\182\195\159t du unerwartet auf einen verbliebenen \195\156berlebenden. Die unbekannte Person warf den Kopf des zuletzt erledigten C.\194\176O.s zu Boden und blickt dann zu dir her\195\188ber."
L4_1[1] = L5_1
