L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_UNIT_SKILL_DESC_CA_STREGA_YOO_NA_PASSIVE_LV5"
L4_1 = "Zus\195\164tzlich zum Passiveffekt wird pro Sekunde ein LP-Verringerungs-Debuff auf generische Einheiten angewendet (nicht entfernbar, au\195\159er bei Bossen). Der Debuff-Wert wird mit 3 % angewendet, wenn sich nur eine generische Einheit in Reichweite befindet, und mit jeder weiteren Anzahl verringert er sich um 1 % (mind. 1 %)."
