L43_1 = "SI_UNIT_SKILL_DESC_C_ESPR_SHADOW_HYPER_LV1"
L44_1 = "Entfesselt die Wesen, die in ihr schlummern, und verursacht Fl\195\164chenschaden an den Feinden vor ihr. Feinde verlieren f\195\188r 12\194\160Sekunden 30\194\160% TRF. Beim Wirken einer F\195\164higkeit werden vorne 5 Kreaturen beschworen."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_UNIT_SKILL_DESC_DELTA_CA_JAKE_SKILL_LV1"
L45_1 = "Kombiniert zwei Fertigkeiten, f\195\188gt Fl\195\164chenschaden zu und zielt 6 Sekunden lang auf den Wirkenden. Wird nach Wirken f\195\188r 12 Sekunden immun gegen Bet\195\164ubungstreffer durch Spezialf\195\164higkeiten oder niedriger und Bet\195\164ubung\226\151\135. ATMP erh\195\182ht sich f\195\188r 12 Sekunden um 45\194\160% (nicht entfernbar)."
L43_1[1] = L44_1
L43_1[2] = L45_1
