L50_1 = "F\195\188r 13\194\160s nach F\195\164higkeitsanwendung Immunit\195\164t gegen Bet\195\164ubungstreffer von Spezialf\195\164higkeiten oder niedriger, Counterabwehr-SDN + 80 %, Spezialf\195\164higkeiten-SDN + 30 %"
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
