L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_SKILL_DESC_ROOT_C_DEMON_ATTACK_LV1"
L9_1 = "Schie\195\159t mit einer riesigen Armbrust und f\195\188gt Gegnern vor sich Schaden zu. Erh\195\182ht nach dem Einsatz von Spezialf\195\164higkeiten oder Ultimate-F\195\164higkeiten den Schaden von Standardangriffen f\195\188r 3 Angriffe um 74\226\128\175 %. Diese Angriffe verursachen immer KRIT-Schaden und priorisieren Vorhutk\195\164mpfer in Reichweite."
L7_1[1] = L8_1
L7_1[2] = L9_1
