L22_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_RAS_MA_TOWER_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_RAS_MA_TOWER_LOBBY_TOUCH_NORMAL_4"
L23_1 = "A wish to become human? I don't need that kind of wish anymore. Humans can freely leave whenever they want, but dolls always stay right where they are. So don't worry, Daddy. I'll forever be your doll."
L21_1[1] = L22_1
