L41_1 = "SI_PF_DEFENCE_BANNER_02_DESC_11"
L42_1 = "<b><color=#ffd34c>[Erscheinung von Gegnern und Kill-Punkte]</color></b>\n\n\226\128\147 <b>Regelm\195\164\195\159iges Erscheinen von Gegnern:</b> M\195\164chtige Gegner tauchen regelm\195\164\195\159ig auf.\n\n\226\128\147 <b>Erhalt von Killpunkten:</b> Wenn du ein Monster t\195\182test, erh\195\164ltst du je nach Monster-Stufe unterschiedliche Killpunkte.\n\n\226\128\147 <b>Rangpriorit\195\164t:</b> Wenn die Killpunkte gleich sind, wird der Spieler, der zuerst in der Rangliste registriert wurde, h\195\182her eingestuft.\n\n\n<b><color=#ffd34c>[Einsatz der Mitarbeiter]</color></b>\n\n\226\128\147 <b>Erweiterter Einsatzbereich:</b> Der Einsatzbereich aller verb\195\188ndeten Mitarbeiter wurde erweitert.\n\n\226\128\147 <b>Anpassung der Einheiten-Slots:</b> Die Anzahl der Einheitenslots wird auf 4 reduziert.\n\n\226\128\147 <b>Anpassung der Einsatzh\195\164ufigkeit:</b> Es gibt keine Begrenzung der Eins\195\164tze.\n\n\226\128\147 <b>Anpassung der Einsatzkosten:</b> Die Einsatzkosten werden auf 10 festgelegt.\n\n\n<b><color=#ffd34c>[Schwierigkeitsanstieg mit der Zeit]</color></b>\n\n\226\128\147 <b>Gew\195\164hrung von Immunit\195\164t gegen Bet\195\164ubungstreffer:</b> Ab 1 Minute nach Beginn des Kampfes wird allen gegnerischen Einheiten Immunit\195\164t gegen Bet\195\164ubungstreffer gew\195\164hrt.\n\n\226\128\147 <b>SDN-Erh\195\182hung:</b> Erh\195\182ht ab 2 Minuten nach Beginn des Kampfes den verursachten Schaden von allen gegnerischen Einheiten um 100 %.\n\n\n<b><color=#ffd34c>[Kampfumgebung]</color></b>\n\n\226\128\147 <b>Kampfzeit:</b> Die Kampfzeit ist auf 3 Minuten begrenzt."
L40_1[1] = L41_1
L40_1[2] = L42_1
