L6_1 = "Titel: S1 Expeditions-Eroberer"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_TITLE_SS_OMEN_5"
L7_1 = "Omen"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_NAME_SS_OMEN_5"
L8_1 = "La traviata"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_DESC_1_SS_OMEN_5"
L9_1 = "Zwischen Normalside und Counterside, Geschichte und Erfindung, Pflicht und Grund irrt sie umher.\nUnd als sie endlich eine neue B\195\188hne betritt, wird ihre Geschichte zu einem Gru\195\159 des Beifalls an jene, die hinter dem Vorhang warten."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_PROLOGUE"
L10_1 = "Zur Zeit der Multinationalen Vereinten Streitkr\195\164fte setzte Richard Werner sein Leben aufs Spiel, um Charade zu verteidigen.\nMit den Jahren wurde er zum Veteranen, und noch immer widmet er dieser Stadt seine ganze Hingabe."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE1"
L11_1 = "Die Mindestvoraussetzung f\195\188r einen offiziell anerkannten Counter jeder Stadt ist der Rang S.\nNat\195\188rlich ist das nur die minimale Voraussetzung."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_1"
L12_1 = "Rote Schuhe"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_1"
L13_1 = "Mit diesen roten Schuhen kann ich \195\188berallhin gehen.\nSelbst wenn meine F\195\188\195\159e darin brennen und ich nicht mehr aufh\195\182ren kann zu tanzen, werde ich trotzdem zu Ihnen laufen. Ganz gleich, wo du bist."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_2"
L14_1 = "Bankett der Hunde"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_2"
L15_1 = "Der Jagdhund hetzt die Beute f\195\188r seinen Herrn.\nDer Kampfhund k\195\164mpft f\195\188r seinen Herrn gegen andere Hunde.\nDoch wof\195\188r ein tollw\195\188tiger Hund seine Z\195\164hne fletscht, wei\195\159 niemand."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE2"
L16_1 = "Sie wei\195\159 es.\nDass sehen zu k\195\182nnen, was andere nicht sehen k\195\182nnen, keine Gabe ist,\nsondern etwas, das einem Fluch n\195\164herkommt."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE3"
L17_1 = "Offiziell ist sie Gesch\195\164ftsf\195\188hrerin von Jonie & Melonie und eine Top-Anw\195\164ltin.\nW\195\164hrend sie durch F\195\164lle aus Politik und Wirtschaft an Einfluss gewann, ist ihre wahre Identit\195\164t als Lamda Spatari nur wenigen bekannt."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_3"
L18_1 = "Abartiges Wesen"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_3"
L19_1 = "Ein Wesen der Einsamkeit, verloren und allein.\nJe verzweifelter es darum ringt, dieser Isolation zu entkommen,\nje mehr es andere verschlingt, um seiner Leere zu entfliehen,\ndesto unausweichlicher bleibt der Hunger, der es niemals satt werden l\195\164sst."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_4"
L20_1 = "Walfang"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_4"
L21_1 = "Ein offizieller Counter zum Schutz der sechs St\195\164dte der Administration verf\195\188gt \195\188ber weitreichende Befugnisse.\nEines davon ist die tempor\195\164re Kontrolle aller st\195\164dtischen Einrichtungen im Katastrophenfall."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_5"
L22_1 = "Pfad zur G\195\182ttlichkeit"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_5"
L23_1 = "Zwischen dem Imagin\195\164ren und der Wirklichkeit, zwischen Materie und Idee, zwischen Fleisch und Geist ...\nliegt ein Pfad verborgen.\nDer Pfad, auf dem am Ende jeder Mensch g\195\182ttlich werden kann."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE4"
L24_1 = "Vom ehrenhaften zum feigen L\195\182wen."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE5"
L25_1 = "Endlich setzt sich der stillstehende Zeiger wieder in Bewegung. Und das als Zufall verkleidete Schicksal zeigt sein wahres Gesicht."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
