L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_GET_01"
L15_1 = "It's been a while, Supreme Administrator. I'm Doctor Macy. There's only one reason I'm cooperating with you. Because if Commander were still here, she'd make the same choice."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_CAPTAIN"
L16_1 = "Fine. Mind if I take a look around your office? I'm curious how many cute Artifacts you've been hoarding."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_CONNECT"
L17_1 = "There were so many half-baked facilities that I just started modifying them myself. Huh? The electricity bill? Like I'd ever worry about something like that."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_CONNECT_LIFETIME"
L18_1 = "What am I doing? Inspecting your office. You've got too many enemies. You never know when or where a risk might pop up. Hey, wait! I haven't checked that drawer yet! Stay right there!"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_TOUCH_NORMAL_1"
L19_1 = "The reason I stayed until the very end of Future-at-War is simple. To carry on Commander's will and save everyone. That's also why I'm working with you."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_TOUCH_NORMAL_2"
L20_1 = "That Terrabrain that calls you \"Daddy\"... It's a mass-projected hologram, right? It's not my field, but it caught my interest. I'll need to stay close and figure out how it works."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_TOUCH_NORMAL_3"
L21_1 = "These sunflower seeds? They taste exactly the same as they did twenty years ago. That's why I keep eating them. Somehow... it feels like I'm back in those noisy days again."
