L22_1 = "So these are the hidden files on the Supreme Administrator's computer. Ooh... So this is your taste...? All right, I'll use this as leverage\226\128\147 E-eep?! S-since when were you standing there?"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
