L23_1 = "I built you a self-contained portable workshop. I call it the \"work cell\" for short. A genius like you shouldn't waste time. Go on, get inside and work. I'll pass your meals through this slot."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_TOUCH_LIFETIME_2"
L24_1 = "Engineers don't count on luck, we make it real. Just like you did. Someday... I'll become someone like you, saving people along the way."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_TOUCH_LIFETIME_3"
L25_1 = "Dr. Ember was my refuge when all I could think about was waking the frozen Deputy Commander. When I heard she went missing... it felt just like when I lost the Commander."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
