L7_1 = "SI_PF_UNIT_TACTIC_UPDATE_DESC_3"
L8_1 = "<color=#FF0000>\226\128\187 Wenn sich unter den ausgew\195\164hlten Mitarbeitern ein Mitarbeiter mit einer h\195\182heren Verbesserungsstufe befindet, erfolgt die \195\156bertragung mit der h\195\182chsten Verbesserungsstufe desselben Mitarbeiters.\nTaktisches Updates werden stufenweise kumulativ angewendet.</color>\n<color=#CF0B0B>\195\156bertragbare Verst\195\164rkungsstufen: Erfahrung, Limitfusion, F\195\164higkeitsstufe, Taktisches Update, Loyalit\195\164t</color>"
