L22_1 = "SI_UNIT_SKILL_DESC_FRONTBAY_C_HARPOON_SKILL_LV5"
L23_1 = "Wendet unabh\195\164ngig vom Cooldown die Spezialf\195\164higkeit an, wenn die LP auf 50 % oder weniger fallen"
