L27_1 = "SI_DP_KEYWORD_DESC_UNIT_FRONTBAY_C_HARPOON_PASSIVE"
L28_1 = "Pro Stapelung Erlittene SDN-Dezimierung +1 %, bei Erreichen der max. Stapelungen wird Perfektes ASW\226\151\135 aktiviert"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_GET_01"
L29_1 = "So you're the captain of this ship? Name's Kiera Bonny. The one who's gonna become the next great pirate of this age. You look kinda flimsy at first glance... You sure you can make it through these rough seas?"
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_CAPTAIN"
L30_1 = "All right, Captain's orders! Hoist the anchor and get ready to set sail!"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_CONNECT"
L31_1 = "Captain. We don't have time to stand around. Get the ship ready. We're heading out to sea to write a new legend."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_CONNECT_LIFETIME"
L32_1 = "I've been waiting. No matter how rough the seas get, if I'm with you, Captain, we'll make it through. You ready to sail?"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_NORMAL_1"
L33_1 = "I hate being tied down. I don't know how great you really are, Captain, but if you try to bind me for some lousy reason, I won't stay quiet. I'll smash everything in my way."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_NORMAL_2"
L34_1 = "The Great Pirate Avery gave people a tomorrow. If I free this city and give people a tomorrow too... then maybe I can inherit the title of great pirate, right?"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_NORMAL_3"
L35_1 = "Hey, Captain. About your daughter... I heard she was an infamous pirate herself. Breaking prisoners out of jail, fighting bounty hunters and all that... You know, she might actually make a good rival for the title of great pirate."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_NORMAL_4"
L36_1 = "If I weren't a pirate? Maybe I'd have joined some TASKFORCE like the others and lived a cushy life. But I like things the way they are now. I'm free. Not tied down to anyone."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_LIFETIME_1"
L37_1 = "Back then, I would've said someone aiming to be a great pirate doesn't need companions. But sailing with you, Captain... I've changed my mind. Having at least one person by my side doesn't sound so bad."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_LIFETIME_2"
L38_1 = "If your body feels stiff, come lie down here. With my ability, I can help loosen up those tight muscles. I-I'm only doing this because you're the captain! Don't get the wrong idea. I wouldn't do this for anyone else!"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_LIFETIME_3"
L39_1 = "You say my expression changes when I laugh? W-well... I heard pirates are supposed to laugh big and loud, so... I-I practiced laughing like that. D-don't laugh! That's one of a pirate's dreams, okay?!"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON@AB_UI_UNIT_VOICE_NKM_UNIT_FRONTBAY_C_HARPOON_LOBBY_TOUCH_LIFETIME_4"
L40_1 = "I don't really like the Administration. But that doesn't mean I want to hurt the people working there. So... could you stop telling me to get therapy from that shady fortune-teller already? I'm way more normal than you think, Captain."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
