L37_1 = "SI_UNIT_SKILL_DESC_G1_C_TAOIST_PASSIVE_LV5"
L38_1 = "F\195\188r jede gegnerische Unterst\195\188tzer-Einheit auf dem Schlachtfeld erh\195\182ht sich das eigene F\195\164higkeitentempo um +15 % (max. +45 %, nicht entfernbar)."
