L20_1 = "SI_SKILL_DESC_OPR_CREW"
L21_1 = "Verleiht <color=#ffd34c>allen verb\195\188ndeten Einheiten</color> f\195\188r <color=#ffd34c>{time}\194\160Sekunden</color> <color=#ffd34c>+{factor1}\194\160% auf {stat1}</color>. Solange der Buff aktiv ist, erhalten <color=#ffd34c>verb\195\188ndete Vorhutk\195\164mpfer</color> [#UNIT_OPR_CREW_STRIKER#] und <color=#ffd34c>verb\195\188ndete Verteidiger</color> [#UNIT_OPR_CREW_DEFENDER#]. Dieser Effekt <color=#ffd34c>kann nicht aufgehoben werden</color>."
L19_1[1] = L20_1
L19_1[2] = L21_1
