L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CAT_ACC_A"
L27_1 = "Ein Ger\195\164t, das das Avesta-Laufwerk miniaturisiert. Ein System, das Verderbniswellen absorbiert und in Antrieb umwandelt. F\195\188r den menschlichen K\195\182rper eigentlich ungeeignet, doch der Wille, andere zu retten, hat diese Grenze \195\188berwunden."
