L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_RAS_C_RIBBON_PASSIVE_LV1"
L8_1 = "Wenn eine beschworene Einheit mit einem Standardangriff getroffen wird, wird zus\195\164tzlicher Schaden verursacht, der Bet\195\164ubungstreffer verursacht. Wenn au\195\159erdem alle beschworenen Einheiten auf dem Schlachtfeld fliehen, werden ihre LP 2 Sekunden lang um 5 % pro Sekunde wiederhergestellt und ANG erh\195\182ht sich permanent um 6 % und KRIT-SDN um 5 % (max. 15 Stapelungen)."
