L13_1 = "SI_UNIT_SKILL_DESC_DREAM_C_WRITER_PASSIVE_LV1"
L14_1 = "L\195\164dt bei einem Einsatz die Wutz\195\164hlung aller Verb\195\188ndeten mit einer Wut-Kennzeichnung 6-mal auf. Zus\195\164tzlich wird die Wutz\195\164hlung der Verb\195\188ndeten mit Wut-Kennzeichnung in Reichweite von 250 um den Einsatzpunkt 3-mal zus\195\164tzlich aufgeladen. Fallen die eigenen LP auf 30 % oder darunter, wird sie f\195\188r einen Moment unverwundbar und das Ultimate-Cooldown wird um 30 Sekunden verringert."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_SKILL_DESC_DREAM_C_WRITER_HYPER_LV1"
L15_1 = "Beim Wirken erhalten alle Gegner im Radius von 500 um den Anwender f\195\188r 15 Sekunden -30 % ATMP. Anschlie\195\159end kehrt der Anwender zu seinem Einsatzpunkt zur\195\188ck und stellt dabei 100 % seiner LP wieder her. Nach der R\195\188ckkehr an den Einsatzpunkt wird der Einsatzeffekt erneut ausgel\195\182st."
L13_1[1] = L14_1
L13_1[2] = L15_1
