L13_1 = "Ein Mann, der sich nach der Vergangenheit sehnt. Doch was er schlie\195\159lich vor sich findet, ist nicht die Vergangenheit, sondern eine un\195\188berbr\195\188ckbare Kluft. Eine andere Welt."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT2_INTERLUDE_2"
